{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';

const port = Number(process.env.PORT || 8080);
const database = new DatabaseSync(process.env.DB_PATH || './workboard.sqlite');
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at INTEGER NOT NULL
  )
`);

const listProjects = database.prepare('SELECT id, name FROM projects ORDER BY created_at, rowid');
const findProject = database.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function handle(request, response) {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  if (url.pathname === '/health' && request.method === 'GET') {
    return json(response, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && request.method === 'GET') {
    return json(response, 200, listProjects.all());
  }
  if (url.pathname === '/api/projects' && request.method === 'POST') {
    let body;
    try {
      body = await new Promise((resolve, reject) => {
        let data = '';
        request.setEncoding('utf8');
        request.on('data', (chunk) => { data += chunk; });
        request.on('end', () => {
          try { resolve(JSON.parse(data || '{}')); } catch (error) { reject(error); }
        });
        request.on('error', reject);
      });
    } catch {
      return json(response, 400, { error: 'Invalid JSON' });
    }
    const name = typeof body.name === 'string' ? body.name.trim() : '';
    if (!name) return json(response, 400, { error: 'Project name is required' });
    const project = { id: randomUUID(), name };
    createProject.run(project.id, project.name, Date.now());
    return json(response, 201, project);
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (projectMatch && request.method === 'GET') {
    const project = findProject.get(decodeURIComponent(projectMatch[1]));
    return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
  }

  const assetPath = url.pathname === '/' ? 'index.html' : normalize(url.pathname).replace(/^([/\\]|\.\.(?:[/\\]|$))+/, '');
  const filePath = join(process.cwd(), 'public', assetPath);
  try {
    const content = await readFile(filePath);
    const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };
    response.writeHead(200, { 'Content-Type': types[extname(filePath)] || 'application/octet-stream' });
    response.end(content);
  } catch {
    response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    response.end('Not found');
  }
}

createServer((request, response) => {
  handle(request, response).catch(() => {
    if (!response.headersSent) json(response, 500, { error: 'Internal server error' });
    else response.destroy();
  });
}).listen(port, '0.0.0.0');
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const form = document.querySelector('#create-form');
const nameInput = document.querySelector('#project-name');
const errorMessage = document.querySelector('#error-message');
const projectsElement = document.querySelector('#projects');

async function request(path, options) {
  const response = await fetch(path, options);
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'Something went wrong');
  return value;
}

function showList() {
  listView.hidden = false;
  detailView.hidden = true;
  document.title = 'Workboard';
}

async function renderProjects() {
  const projects = await request('/api/projects');
  projectsElement.replaceChildren();
  for (const project of projects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => {
      history.pushState({}, '', `/projects/${encodeURIComponent(project.id)}`);
      renderRoute();
    });
    row.append(name, open);
    projectsElement.append(row);
  }
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/([^/]+)\/?$/);
  if (!match) {
    showList();
    await renderProjects();
    return;
  }
  try {
    const project = await request(`/api/projects/${encodeURIComponent(decodeURIComponent(match[1]))}`);
    document.querySelector('#project-title').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    listView.hidden = true;
    detailView.hidden = false;
  } catch {
    history.replaceState({}, '', '/');
    showList();
    await renderProjects();
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  errorMessage.hidden = true;
  const name = nameInput.value.trim();
  if (!name) {
    errorMessage.textContent = 'Project name is required';
    errorMessage.hidden = false;
    nameInput.focus();
    return;
  }
  try {
    await request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    form.reset();
    await renderProjects();
    nameInput.focus();
  } catch (error) {
    errorMessage.textContent = error.message;
    errorMessage.hidden = false;
  }
});

document.querySelector('#back-button').addEventListener('click', () => {
  history.pushState({}, '', '/');
  renderRoute();
});
window.addEventListener('popstate', renderRoute);
renderRoute();
