<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <link rel="stylesheet" href="/styles.css">
    <script type="module" src="/app.js"></script>
  </head>
  <body>
    <main class="page">
      <header class="topbar"><h1>Workboard</h1></header>
      <section id="project-list" aria-labelledby="page-title">
        <h2 id="page-title">Projects</h2>
        <form id="create-form">
          <label for="project-name">Project name</label>
          <div class="form-row">
            <input id="project-name" name="name" type="text" autocomplete="off">
            <button type="submit">Create project</button>
          </div>
          <p id="error-message" class="error" role="alert" hidden></p>
        </form>
        <div id="projects" class="projects" aria-live="polite"></div>
      </section>
      <section id="project-detail" hidden>
        <button id="back-button" type="button">Projects</button>
        <h2 id="project-title"></h2>
      </section>
    </main>
  </body>
</html>
:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #f4f6fa;
}

* { box-sizing: border-box; }
body { margin: 0; }
.page { width: min(760px, calc(100% - 32px)); margin: 48px auto; }
.topbar { border-bottom: 1px solid #dce2ec; margin-bottom: 32px; }
h1 { margin: 0 0 18px; font-size: 2rem; }
h2 { margin: 0 0 24px; font-size: 1.4rem; }
form { padding: 22px; background: #fff; border: 1px solid #dce2ec; border-radius: 10px; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row { display: flex; gap: 10px; }
input { min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #aeb9ca; border-radius: 6px; font: inherit; }
button { padding: 10px 14px; border: 0; border-radius: 6px; background: #315bd6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #2448b2; }
button:focus-visible, input:focus-visible { outline: 3px solid #9db5ff; outline-offset: 2px; }
.projects { margin-top: 18px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 10px; padding: 14px 16px; background: white; border: 1px solid #dce2ec; border-radius: 8px; }
.project-row span { overflow-wrap: anywhere; }
.error { margin: 12px 0 0; color: #a2212b; }
#back-button { margin-bottom: 24px; background: #e7ecf7; color: #172033; }
#back-button:hover { background: #d8e0f0; }
[hidden] { display: none !important; }

@media (max-width: 520px) {
  .page { margin-top: 28px; }
  .form-row { align-items: stretch; flex-direction: column; }
  .project-row { align-items: stretch; flex-direction: column; }
}
